  let result,usage = K.check_with_usage ~until request candidate assembly history in
  require (E.Result.passed result && usage.authority_work > 0 && usage.reconstruction_work > 0 &&
    usage.work_charged > usage.authority_work + usage.reconstruction_work)
    "Source acceptance, independent declarations or actual reconstructed behavior was skipped";
  let actual = case "actual_in_band_witness" in
  require (get "candidate" actual <> get "candidate" baseline && E.Result.passed (run actual))
    "Checker replaced accepted actual candidate authority with the default generated graph";
  let relocated = case "relocated_source" in
  let relocated_request,relocated_candidate,relocated_assembly,_,_ = arguments relocated in
  require (Realization_request.fingerprint relocated_request = Realization_request.fingerprint request &&
    Synthetic_authority.Candidate.fingerprint relocated_candidate = Synthetic_authority.Candidate.fingerprint candidate &&
    Component_assembly.fingerprint relocated_assembly <> Component_assembly.fingerprint assembly)
    "Relocated exact source coordinates were lost or incorrectly became source semantic identity";
  rejected "component_assembly" (fun () -> K.check ~until relocated_request relocated_candidate assembly history);
  let parent = W.create ~profile:"literal.component_assembly" ~error_code:"literal_assembly_parent" ~maximum:50_000_000 () in
  let repeated,nested = K.check_with_usage ~until ~parent request candidate assembly history in
  require (E.Result.fingerprint repeated = E.Result.fingerprint result && nested.work_charged = usage.work_charged &&
    W.remaining parent = 50_000_000 - nested.work_charged)
    "A synthetic, declaration, reconstruction, composition or behavior phase escaped the parent budget";
  let tiny = W.create ~profile:"literal.component_assembly" ~error_code:"literal_assembly_parent" ~maximum:1 () in
  rejected "literal_assembly_parent" (fun () -> K.check ~until ~parent:tiny request candidate assembly history);
  List.iter (fun (code,limits) -> rejected code (fun () -> K.check ~until ~limits request candidate assembly history))
    ["realization_work_limit",K.make_limits ~max_work:1 ();
     "realization_input_limit",K.make_limits ~max_request_bytes:1 ();
     "realization_report_limit",K.make_limits ~max_report_bytes:1 ();
     "realization_report_limit",K.make_limits ~max_report_nodes:1 ();
     "realization_monitor_limit",K.make_limits ~max_monitor_items:1 ()];
  let exact_input = K.check ~until ~limits:(K.make_limits ~max_request_bytes:usage.request_bytes ())
    request candidate assembly history in
  require (E.Result.fingerprint exact_input = E.Result.fingerprint result) "Exact cumulative input byte boundary rejected";
  rejected "realization_input_limit" (fun () -> K.check ~until
    ~limits:(K.make_limits ~max_request_bytes:(usage.request_bytes - 1) ()) request candidate assembly history);
  let exact_report = K.check ~until ~limits:(K.make_limits ~max_report_bytes:usage.report_bytes ())
    request candidate assembly history in
  require (E.Result.fingerprint exact_report = E.Result.fingerprint result) "Exact cumulative authority/report boundary rejected";
  rejected "realization_report_limit" (fun () -> K.check ~until
    ~limits:(K.make_limits ~max_report_bytes:(usage.report_bytes - 1) ()) request candidate assembly history);
  let first = List.hd history in
  let rec cyclic_history = first :: cyclic_history in
  rejected "realization_input_limit" (fun () -> K.check ~until request candidate assembly cyclic_history);
  let wrong = List.find (fun raw -> Json.string (get "name" raw) = "parameter_method") mutations in
  let changed = Component_assembly.of_json (get "assembly" wrong) in
  let failed_parent = W.create ~profile:"literal.component_assembly.failure" ~error_code:"literal_assembly_failed_parent" ~maximum:50_000_000 () in
  rejected "component_assembly" (fun () -> K.check ~until ~parent:failed_parent request candidate changed history);
  let after_failure = W.remaining failed_parent in
  require (after_failure > 0 && after_failure < 50_000_000) "A failed source comparison omitted work or falsely burned future capacity";
  rejected "component_assembly" (fun () -> K.check ~until ~parent:failed_parent request candidate changed history);
  require (W.remaining failed_parent < after_failure) "Repeated failed checks reused unchecked authority or fresh work capacity";
  require (E.Result.fingerprint (K.check ~until request candidate assembly history) = E.Result.fingerprint result)
    "Failed authority or cyclic input contaminated an independent assembly check";
  print_endline "component assembly: 12 full independent Python reports, 14 exact provenance/acceptance rejections, actual candidate and relocated source authority, shared bounds and failure isolation checked"
